import { Platform } from 'react-native'
import * as StoreReview from 'expo-store-review'
import AsyncStorage from '@react-native-async-storage/async-storage'

const LAST_REVIEW_REQUEST_KEY = 'anything_last_review_request'
const DAYS_BETWEEN_PROMPTS = 7

export const prePromptStoreRating = async (force = false) => {
	if (Platform.OS !== 'ios') return

	try {
		const isAvailable = await StoreReview.isAvailableAsync()
		if (!isAvailable) return

		if (!force) {
			const lastRequest = await AsyncStorage.getItem(LAST_REVIEW_REQUEST_KEY)
			const now = Date.now()
			if (lastRequest) {
				const last = Number(lastRequest)
				const diffDays = (now - last) / (1000 * 60 * 60 * 24)
				if (diffDays < DAYS_BETWEEN_PROMPTS) return
			}

			await AsyncStorage.setItem(LAST_REVIEW_REQUEST_KEY, String(now))
		}

		await StoreReview.prePromptReview()
	} catch (err) {
		console.warn('Failed to pre-prompt review', err)
	}
}
